int unboundedKnapsackDP_28(const vector<int>& wt, const vector<int>& val, int W) { vector<int> dp(W + 1, 0); for (int w = 1; w <= W; ++w) for (size_t i = 0; i < wt.size(); ++i) if (wt[i] <= w) dp[w] = max(dp[w], dp[w - wt[i]] + val[i]); return dp[W]; }
int lisQuadraticDP_28(const vector<int>& a) { int n = a.size(), mx = 0; vector<int> dp(n, 1); for (int i = 0; i < n; ++i) { for (int j = 0; j < i; ++j) if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1); if (dp[i] > mx) mx = dp[i]; } return mx; }
int minPathSumGrid_28(const vector<vector<int>>& grid) { int n = grid.size(), m = grid[0].size(); vector<vector<int>> dp(n, vector<int>(m, 0)); dp[0][0] = grid[0][0]; for (int i = 1; i < n; ++i) dp[i][0] = dp[i - 1][0] + grid[i][0]; for (int j = 1; j < m; ++j) dp[0][j] = dp[0][j - 1] + grid[0][j]; for (int i = 1; i < n; ++i) for (int j = 1; j < m; ++j) dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]; return dp[n - 1][m - 1]; }
int kadaneMaxSubarray_28(const vector<int>& a) { int best = a[0], cur = a[0]; for (size_t i = 1; i < a.size(); ++i) { cur = max(a[i], cur + a[i]); best = max(best, cur); } return best; }
